struct DDBEntry {
    uint8_t _offset[3];   // 24-bit offset into DDB_STRINGS
    uint32_t offset() const {
        return (uint32_t(_offset[0]) << 16) |
               (uint32_t(_offset[1]) << 8)  |
               (uint32_t(_offset[2]));
    }
    const char *reg() const { return &DDB_STRINGS[offset()]; }
};

